import React, { useEffect, useState } from "react";
import axios from "axios";

function LevelList() {
  const [levels, setLevels] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:5000/levels")
      .then(res => setLevels(res.data));
  }, []);

  const completeLevel = (level) => {
    axios.post("http://localhost:5000/complete", { level })
      .then(() => window.location.reload());
  };

  return (
    <div>
      {levels.map(lvl => (
        <div key={lvl.id} style={{ margin: 10 }}>
          <button
            disabled={!lvl.is_unlocked}
            onClick={() => completeLevel(lvl.level)}
          >
            Level {lvl.level}
          </button>

          {lvl.is_completed && " ✅ Completed"}
          {!lvl.is_unlocked && " 🔒 Locked"}
        </div>
      ))}
    </div>
  );
}

export default LevelList;
